#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ReasonClass { Reject, CommittedFailure }

/// Stable catalogued reason identifiers.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum ReasonId {
    /// `denied` at precedence 0.
    Reason200 = 200,
    /// `capacity` at precedence 1.
    Reason201 = 201,
    /// `recorded_failure` at precedence 2.
    Reason202 = 202,
}

impl ReasonId {
    pub const fn get(self) -> u32 { self as u32 }
    pub fn try_semantic_id(self) -> Result<SemanticId, ProfileError> {
        SemanticId::try_new(self.get())
    }
    pub const fn class(self) -> ReasonClass {
        match self {
            Self::Reason200 => ReasonClass::Reject,
            Self::Reason201 => ReasonClass::Reject,
            Self::Reason202 => ReasonClass::CommittedFailure,
        }
    }
}

/// Stable catalogued ordinary rejection identifiers.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RejectReasonId {
    /// `denied` at precedence 0.
    Reason200,
    /// `capacity` at precedence 1.
    Reason201,
}

impl RejectReasonId {
    /// Returns the corresponding general generated reason.
    pub const fn reason_id(self) -> ReasonId {
        match self {
            Self::Reason200 => ReasonId::Reason200,
            Self::Reason201 => ReasonId::Reason201,
        }
    }
    /// Reconstructs the reviewed nonzero semantic identifier.
    pub fn try_semantic_id(self) -> Result<SemanticId, ProfileError> {
        self.reason_id().try_semantic_id()
    }
}

/// Stable catalogued committed failure identifiers.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CommittedFailureReasonId {
    /// `recorded_failure` at precedence 2.
    Reason202,
}

impl CommittedFailureReasonId {
    /// Returns the corresponding general generated reason.
    pub const fn reason_id(self) -> ReasonId {
        match self {
            Self::Reason202 => ReasonId::Reason202,
        }
    }
    /// Reconstructs the reviewed nonzero semantic identifier.
    pub fn try_semantic_id(self) -> Result<SemanticId, ProfileError> {
        self.reason_id().try_semantic_id()
    }
}

